def count_primes(n):
    if n <= 2:
        return 0
    flags = bytearray([1]) * n
    flags[0] = flags[1] = 0
    prime = 2
    while prime * prime < n:
        if flags[prime]:
            start = prime * prime
            flags[start:n:prime] = bytes((n - 1 - start) // prime + 1)
        prime += 1
    return sum(flags)

